function featuresPage(){return intro('Everything, in perspective.','A tour of the proposed FYNX Wallet. Nothing here is live yet.',`<nav class="tour-jump" aria-label="Jump to a feature">${featureTour.map(([id,name])=>`<button type="button" class="tour-chip" data-target="ft-${id}">${name}</button>`).join('')}<button type="button" class="tour-chip" data-target="ft-review">Review screen</button></nav>${featureTour.map(([id,name,title,status,body,points,mock],i)=>`<section class="ft-row${i%2?' flip':''}" id="ft-${id}" aria-labelledby="ft-${id}-h"><div class="ft-copy"><span class="eyebrow">${String(i+1).padStart(2,'0')} · ${name}</span><h2 id="ft-${id}-h">${title}</h2><span class="ft-status">${status}</span><p class="muted">${body}</p><ul class="ft-points">${points.map(p=>`<li>${p}</li>`).join('')}</ul></div><div class="ft-mock" aria-label="Illustrative ${name.toLowerCase()} preview"><div class="between"><b>${name}</b><span class="tiny">Illustrative · example values</span></div>${mock.map(([k,v])=>`<div class="ft-mock-row"><span>${k}</span><b>${v}</b></div>`).join('')}</div></section>`).join('')}<section class="card review-tour" id="ft-review" aria-labelledby="ft-review-h"><span class="eyebrow">Try it · Example only</span><h2 id="ft-review-h">Walk through the review screen</h2><p class="muted">Before anything is sent, the planned review screen lays out every detail. Tap each line to see what to check. This is an example: nothing is connected and nothing is sent.</p><div class="review-grid"><div class="review-card"><div class="between"><b>Review send</b><span class="tiny">Example</span></div>${reviewSteps.map(([k,v],i)=>`<button type="button" class="review-line" data-step="${i}" aria-pressed="${i===0}" aria-controls="review-explain"><span class="review-num">${i+1}</span><span class="review-k">${k}</span><b>${v}</b></button>`).join('')}</div><div class="review-explain" id="review-explain" role="region" aria-live="polite" aria-label="What to check">${reviewExplain(0)}</div></div></section><div class="info-box">All capabilities are planned. Asset, region, payment-method, and provider availability will be confirmed before launch. Example values on this page are not prices, balances or quotes.</div>${termWords(['self-custody','network-fee','swap','slippage','token-approval','on-ramp','kyc','signing'])}<div class="cta">${button('Join the waitlist ↗')}${button('See planned networks','networks','light')}</div>`)}
function reviewExplain(i){const [,,title,text]=reviewSteps[i];return `<span class="tiny">Step ${i+1} of ${reviewSteps.length}</span><h3>${title}</h3><p>${text}</p><div class="review-nav"><button type="button" class="button light" data-move="-1"${i===0?' disabled':''}>Back</button><button type="button" class="button" data-move="1"${i===reviewSteps.length-1?' disabled':''}>Next step</button></div>`}
function goToSection(t,smooth=true){if(!t)return;t.scrollIntoView({behavior:smooth&&!matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'auto',block:'start'});const h=t.querySelector('h2');if(h){h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}}
function bindFeatures(section=''){const root=$('#app');if(!root||!root.querySelectorAll)return;for(const chip of root.querySelectorAll('.tour-chip[data-target]'))chip.addEventListener('click',()=>{goToSection(document.getElementById(chip.dataset.target));try{history.replaceState(null,'',`#features/${chip.dataset.target.slice(3)}`)}catch{}});if(section)requestAnimationFrame(()=>goToSection(document.getElementById(`ft-${section}`),false));
  const panel=$('#review-explain'),lines=[...root.querySelectorAll('.review-line')];if(!panel)return;let step=0;
  const show=i=>{step=Math.max(0,Math.min(reviewSteps.length-1,i));panel.innerHTML=reviewExplain(step);for(const l of lines)l.setAttribute('aria-pressed',String(Number(l.dataset.step)===step))};
  for(const l of lines)l.addEventListener('click',()=>show(Number(l.dataset.step)));
  panel.addEventListener('click',e=>{const b=e.target.closest('[data-move]');if(b&&!b.disabled)show(step+Number(b.dataset.move))})}
const nextSteps=[['You join','Your email and consent are saved. This page confirms it; no confirmation email is sent.'],['We finish the groundwork','Testing, an independent security review, legal review and payment-provider approvals come before any public access.'],['You hear when it’s ready','When access opens for your region, we email the address you registered. Every update includes a way to unsubscribe.'],['Your record expires','Waitlist records are deleted automatically 365 days after signup. You can ask to be removed at any time.']];
function whatNext(){return `<section class="next-steps" aria-labelledby="next-h"><h2 id="next-h">What happens after you join</h2><ol class="next-list">${nextSteps.map(([t,d],i)=>`<li><span class="number">${String(i+1).padStart(2,'0')}</span><div><b>${t}</b><p class="muted">${d}</p></div></li>`).join('')}</ol><p class="hint">No launch date is promised. See <a href="#faq">Questions</a> or the <a href="#privacy">waitlist privacy notice</a> for details.</p></section>`}
