function networks(){return intro('The right network matters.','Planned coverage. No network is connected in this preview.',`<section class="net-section" id="net-plan" aria-labelledby="plan-h"><h2 id="plan-h">What each network is planned to support</h2><div class="net-table" role="table" aria-label="Planned support by network"><div class="net-row net-head" role="row"><span role="columnheader">Network</span><span role="columnheader">Assets</span>${ACTIONS.map(a=>`<span role="columnheader">${a}</span>`).join('')}</div>${networkPlan.map(([n,assets,status,cells,note])=>`<div class="net-row" role="row"><span class="net-name" role="rowheader"><b>${n}</b><small>${status}</small></span><span role="cell" data-label="Assets">${assets}</span>${cells.map((c,i)=>`<span role="cell" data-label="${ACTIONS[i]}"><i class="net-status ${c.replace(/\s/g,'-').toLowerCase()}">${c}</i></span>`).join('')}<span class="net-note" role="cell">${note}</span></div>`).join('')}</div><p class="hint">“Planned” means intended for a first release; “Possible” means under consideration; “Not yet” means not part of current plans until separate work is done. Nothing here is live, and availability depends on testing, provider approvals and region.</p></section>
<section class="net-section card addr-tool" id="net-check" aria-labelledby="addr-h"><h2 id="addr-h">Which network is this address for?</h2><p class="muted">Paste a wallet address to see what kind of address it is before you send anything. The check runs only in your browser; nothing you type is sent or saved.</p><label class="label" for="addr-input">Wallet address</label><div class="addr-row"><input class="control" id="addr-input" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="e.g. 0x… , bc1… or a Solana address"><button class="button light" type="button" id="addr-clear">Clear</button></div><button class="term-copy addr-copy" type="button" id="addr-copy" hidden>Copy address</button><div class="addr-result" id="addr-result" role="status" aria-live="polite"></div><p class="hint">This checks the address format only. It cannot confirm who owns an address or which network the recipient expects. Always confirm both with the recipient.</p></section>
<div class="info-box">A token on one network cannot be treated as the same balance on another. Sending to the right address on the wrong network can make funds hard or impossible to recover. Supported networks and routes will be explicitly confirmed before launch.</div>${termWords(['network','layer-2','bridge','public-address','checksum','address-poisoning','native-asset','testnet'])}`)}
// Keccak-256 (as used by Ethereum, ASCII input only) for the EIP-55 address checksum check. Runs locally; nothing is sent.
const KRC=['1','8082','800000000000808a','8000000080008000','808b','80000001','8000000080008081','8000000000008009','8a','88','80008009','8000000a','8000808b','800000000000008b','8000000000008089','8000000000008003','8000000000008002','8000000000000080','800a','800000008000000a','8000000080008081','8000000000008080','80000001','8000000080008008'].map(h=>BigInt('0x'+h)),KROT=[1,3,6,10,15,21,28,36,45,55,2,14,27,41,56,8,25,43,62,18,39,61,20,44],KPI=[10,7,11,17,18,3,5,16,8,21,24,4,15,23,19,13,12,2,20,14,22,9,6,1],M64=(1n<<64n)-1n;
function keccak256Hex(text){const bytes=Array.from(String(text),c=>c.charCodeAt(0)&255),rate=136;bytes.push(1);while(bytes.length%rate)bytes.push(0);bytes[bytes.length-1]|=0x80;const s=Array(25).fill(0n),rotl=(x,n)=>((x<<BigInt(n))|(x>>BigInt(64-n)))&M64;
  for(let o=0;o<bytes.length;o+=rate){for(let i=0;i<rate/8;i++){let lane=0n;for(let b=7;b>=0;b--)lane=(lane<<8n)|BigInt(bytes[o+i*8+b]);s[i]^=lane}
    for(let round=0;round<24;round++){const c=[0,1,2,3,4].map(x=>s[x]^s[x+5]^s[x+10]^s[x+15]^s[x+20]);for(let x=0;x<5;x++){const d=c[(x+4)%5]^rotl(c[(x+1)%5],1);for(let y=0;y<25;y+=5)s[y+x]^=d}
      let cur=s[1];for(let i=0;i<24;i++){const j=KPI[i],t=s[j];s[j]=rotl(cur,KROT[i]);cur=t}
      for(let y=0;y<25;y+=5){const r=s.slice(y,y+5);for(let x=0;x<5;x++)s[y+x]=r[x]^((~r[(x+1)%5]&M64)&r[(x+2)%5])}s[0]^=KRC[round]}}
  let out='';for(let i=0;i<4;i++)for(let b=0;b<8;b++)out+=((s[i]>>BigInt(8*b))&255n).toString(16).padStart(2,'0');return out}
function checksumAddress(addr){const lower=addr.slice(2).toLowerCase(),h=keccak256Hex(lower);return '0x'+[...lower].map((ch,i)=>parseInt(h[i],16)>=8?ch.toUpperCase():ch).join('')}
const B58='[1-9A-HJ-NP-Za-km-z]';
function classifyAddress(raw){const v=String(raw||'').trim();if(!v)return null;
  const words=v.split(/\s+/);if(words.length>=12&&words.every(w=>/^[a-z]+$/i.test(w)))return{kind:'danger',title:'Stop: this looks like a recovery phrase.',body:'Never paste your recovery phrase into any website, chat or form. Anyone who has it can take everything in that wallet. The field has been cleared.',clear:true};
  if(/\s/.test(v))return{kind:'warn',title:'Not a single address.',body:'Addresses contain no spaces. Paste one address at a time.'};
  if(/^0x[0-9a-f]{64}$/i.test(v))return{kind:'danger',title:'This is not an address.',body:'64 characters after 0x is the length of a transaction ID or a private key, not a wallet address (which has 40). If this is a private key, never share it with anyone.'};
  if(/^0x[0-9a-f]{40}$/i.test(v)){const body=v.slice(2),mixed=/[a-f]/.test(body)&&/[A-F]/.test(body),plan='FYNX plan: Ethereum is planned first; Base is a possible addition.',same='This same format is used on Ethereum, Base and many other networks, so the address alone does not tell you which network the recipient expects. Confirm the network before sending.';
    if(mixed&&checksumAddress(v)!==`0x${body}`)return{kind:'danger',title:'Checksum does not match: likely a typo.',body:'This address uses mixed capital letters, and they do not match the Ethereum checksum. That usually means a character was mistyped, changed or added. Do not send to it. Copy the address again directly from the recipient.',checksum:'bad'};
    return{kind:'ok',title:'Ethereum-style (EVM) address.',body:`${same} ${mixed?'Checksum verified: its capital letters match, so a typing mistake is very unlikely. This does not prove who owns it.':'It has no mixed capital letters, so a typo cannot be caught from the letters alone. Compare the first and last characters carefully.'}`,plan,checksum:mixed?'ok':'none'}}
  if(/^0x/i.test(v))return{kind:'warn',title:'Incomplete Ethereum-style address.',body:`Ethereum-style addresses are 0x followed by exactly 40 letters (a–f) and numbers. This one has ${v.length-2} characters after 0x${/^0x[0-9a-f]*$/i.test(v)?'':', or contains characters that are not allowed'}. Copy it again from the source.`};
  if(/\.eth$/i.test(v))return{kind:'warn',title:'This is a name, not an address.',body:'Names like this point to an address that the owner can change. Check the full address it points to with the recipient before sending.'};
  if(/^(bc1|tb1)[02-9ac-hj-np-z]{11,71}$/.test(v)||/^(BC1|TB1)[02-9AC-HJ-NP-Z]{11,71}$/.test(v)){const test=/^tb1/i.test(v);return{kind:test?'warn':'ok',title:test?'Bitcoin test-network address.':'Bitcoin address (modern format).',body:test?'Addresses starting with tb1 are for Bitcoin’s test network, which has no real value. Do not send real bitcoin to it.':'Addresses starting with bc1 are used on the Bitcoin network only. Do not send tokens from Ethereum, Base or Solana to it.',plan:'FYNX plan: Bitcoin needs separate work and is not part of the first release.'}}
  if(new RegExp(`^[13]${B58}{25,34}$`).test(v))return{kind:'ok',title:'Most likely a Bitcoin address (older format).',body:'Bitcoin addresses starting with 1 or 3 are used on the Bitcoin network only. Do not send tokens from other networks to it.',plan:'FYNX plan: Bitcoin needs separate work and is not part of the first release.'};
  if(new RegExp(`^${B58}{32,44}$`).test(v))return{kind:'ok',title:'Most likely a Solana address.',body:'Solana addresses are 32–44 letters and numbers without 0x. Only send Solana assets (SOL or Solana tokens) to it.',plan:'FYNX plan: Solana needs separate validation and is not part of the first release.'};
  return{kind:'warn',title:'Not a recognised address format.',body:'It does not match Ethereum, Base, Bitcoin or Solana address formats. Copy the address again directly from the recipient, and avoid retyping it by hand.'}}
function bindAddressTool(){const input=$('#addr-input'),out=$('#addr-result'),clear=$('#addr-clear');if(!input||!out)return;
  const copy=$('#addr-copy');const show=()=>{const r=classifyAddress(input.value);if(copy){copy.hidden=!r||r.kind==='danger';copy.textContent='Copy address'}if(!r){out.innerHTML='';out.className='addr-result';return}if(r.clear)input.value='';out.className=`addr-result ${r.kind}`;out.innerHTML=`<b>${escape(r.title)}</b><p>${escape(r.body)}</p>${r.plan?`<small>${escape(r.plan)}</small>`:''}`};
  input.addEventListener('input',show);if(copy)copy.addEventListener('click',async()=>{const v=input.value.trim(),done=t=>{copy.textContent=t;setTimeout(()=>{copy.textContent='Copy address'},2000)};if(!v)return;try{await navigator.clipboard.writeText(v);done('Address copied')}catch{input.select();done('Selected: press Ctrl+C or ⌘C')}});if(clear)clear.addEventListener('click',()=>{input.value='';show();input.focus()})}
const scamSigns=[
  ['phrase','Someone asked for your recovery phrase, private key or password',true],
  ['verify','You were asked to send crypto to “verify”, “unlock” or “sync” your wallet',true],
  ['fee','You must pay a fee or tax in crypto before you can withdraw winnings or profits',true],
  ['dm','“Support” contacted you first, by direct message, social media or phone',false],
  ['returns','Guaranteed, doubled or risk-free returns are promised',false],
  ['rush','You are being rushed: “act now” or your account will be locked or lost',false],
  ['link','The website address is slightly different from the official one, or came from an ad or message',false],
  ['remote','You were asked to install a screen-sharing or remote-access app',false],
  ['approve','You are asked to approve a transaction or token permission you do not fully understand',false],
  ['romance','Someone you met online, and never in person, is guiding you to invest',false],
];
const approveChecklist=['The website address is exactly the official one, typed or bookmarked by you','The network matches the one the recipient asked for','The recipient address matches in full, not just the first and last characters','The amount, the asset and the total fees are what you expect','You understand what any permission (“approve” or “allow”) lets the other side do','Nobody is rushing you or watching your screen'];
function security(){return intro('Trust starts with clarity.','The security direction for the proposed product, and practical checks you can use today.',`<div class="security-grid">${[['User-controlled signing','The proposed architecture lets users authorize transfers through a wallet provider. No keys are created in this preview.'],['Clear transaction reviews','The product is intended to show asset, recipient, network, rate, and final fees before authorization.'],['Recovery with care','Account and wallet recovery must be designed, tested, and explained before launch.'],['No unverified claims','No audit, certification, insurance, bug bounty, or live account protection is claimed for this prototype.']].map(([t,d])=>`<div class="card security-card"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>
<section class="card scam-check" id="sec-scam" aria-labelledby="scam-h"><span class="eyebrow">SAFETY CHECK</span><h2 id="scam-h">Is this a scam?</h2><p class="muted">Tick anything that has happened. Your answers stay on this page and are not sent anywhere.</p><fieldset class="scam-list"><legend class="sr-only">Warning signs</legend>${scamSigns.map(([id,t])=>`<label class="scam-item"><input type="checkbox" value="${id}"><span>${t}</span></label>`).join('')}</fieldset><div class="scam-result" id="scam-result" role="status" aria-live="polite"></div><button class="button light" type="button" id="scam-reset">Start again</button></section>
<section class="net-section" id="sec-approve" aria-labelledby="approve-h"><h2 id="approve-h">Before you approve anything</h2><ol class="approve-list">${approveChecklist.map(t=>`<li>${t}</li>`).join('')}</ol><p class="hint">Want to practise? <a class="textlink" href="#features/review">Walk through an example review screen ↗</a></p></section>${backupCheck()}${planSheet()}
<div class="security-grid"><div class="card security-card"><h3>How FYNX will contact you</h3><p>Only from <a class="textlink" href="mailto:${CONTACT}">${CONTACT}</a> and this website. FYNX will never ask for your recovery phrase, private key or password, never ask you to send crypto to “verify” anything, and never contact you first by direct message.</p></div><div class="card security-card"><h3>If you think you were targeted</h3><p>Stop replying and do not send anything more. If a wallet may be exposed, move what you can to a new wallet with a new recovery phrase. In the U.S., you can report fraud to the FBI at <a class="textlink" href="https://www.ic3.gov" target="_blank" rel="noopener">ic3.gov</a> and to the FTC at <a class="textlink" href="https://reportfraud.ftc.gov" target="_blank" rel="noopener">reportfraud.ftc.gov</a>.</p></div></div>${termWords(['recovery-phrase','private-key','hardware-wallet','phishing','address-poisoning','token-approval','signing'])}`)}
// [id, statement to tick when true, critical?, what to do if not, glossary slug]
const backupItems=[
  ['offline','My recovery phrase is written on paper or metal, not saved as a photo, screenshot, notes app, email, password manager note or cloud file',true,'Digital copies can be found by malware or anyone who gets into that account. Write the words on paper (or stamp them in metal), then delete every digital copy, including from cloud photo backups and the trash.','recovery-phrase'],
  ['never','I have never typed or pasted it into a website, chat, form, email or “support” request',true,'If you ever did, treat that wallet as exposed. Create a new wallet with a new recovery phrase and move what you can to it. Genuine services never ask for it.','phishing'],
  ['private','Nobody else has seen, photographed or been told the words',true,'Anyone who has the words can take everything in the wallet. If someone else has seen them, moving to a new wallet with a new phrase is the only real fix.','self-custody'],
  ['order','The words are numbered, in the right order, and spelled exactly as the wallet showed them',false,'Compare your copy with the wallet’s backup screen (most wallets let you view it again after unlocking). A wrong or missing word can make the backup useless.','recovery-phrase'],
  ['copies','There are at least two copies, kept in separate safe places',false,'One copy can be lost to fire, flood or a move. Keep a second copy somewhere else you control, such as a safe or a trusted location, never online.',''],
  ['apart','The backup is not kept together with the device and its PIN or password',false,'If a thief finds the device and the phrase together, they have everything. Store them apart.','hardware-wallet'],
  ['extra','If I use an optional extra passphrase (“25th word”), it is backed up too, separately. Tick this if you do not use one.',false,'The phrase alone will not restore a wallet that also used an extra passphrase. Back it up on its own, kept apart from the words.',''],
  ['tested','I have checked that the backup restores the right wallet, for example on a spare device, before holding a large amount',false,'An untested backup can hide a missing word. Restore it with your wallet’s official app on a spare device and check the same address appears. Never test by typing it into a website.','public-address'],
  ['plan','Someone I trust knows a backup exists and where to find instructions if something happens to me',false,'Without a plan, crypto can be lost for good. Many people leave sealed instructions with a will or an attorney, without giving anyone the words in advance.',''],
];
function backupCheck(){return `<section class="card scam-check backup-check" id="sec-backup" aria-labelledby="backup-h"><span class="eyebrow">BACKUP CHECK · ANY WALLET</span><h2 id="backup-h">Is your recovery phrase backup safe?</h2><p class="muted">For any self-custody wallet you use today. Tick each statement that is true. Your answers stay on this page and are not sent or saved. Never type the phrase itself here or anywhere else.</p><fieldset class="scam-list"><legend class="sr-only">Backup statements</legend>${backupItems.map(([id,t])=>`<label class="scam-item"><input type="checkbox" value="${id}"><span>${t}</span></label>`).join('')}</fieldset><div class="scam-result" id="backup-result" role="status" aria-live="polite"></div><button class="button light" type="button" id="backup-reset">Start again</button><p class="hint">Next step: <a class="textlink" href="#security/sheet">make a printable instructions sheet for your family ↗</a></p></section>`}
function backupVerdict(selected){const set=new Set(selected),missing=backupItems.filter(([id])=>!set.has(id)),critical=missing.filter(i=>i[2]),score=backupItems.length-missing.length;
  if(!missing.length)return{kind:'ok',score,title:`${score} of ${backupItems.length}: your backup habits look solid.`,body:'Keep it that way: check your copies once a year, and update your plan when you move or your situation changes.',fixes:[]};
  if(critical.length)return{kind:'danger',score,title:`${score} of ${backupItems.length}: fix ${critical.length===1?'this':'these'} first.`,body:'The red items can let someone else take your crypto. Deal with them before anything else. Statements you did not tick, with what to do:',fixes:[...critical,...missing.filter(i=>!i[2])]};
  return{kind:'warn',score,title:`${score} of ${backupItems.length}: good start, a few gaps to close.`,body:'Nothing urgent, but each statement you did not tick could mean losing access one day. What to do:',fixes:missing}}
function bindBackupCheck(){const root=$('#app'),out=$('#backup-result'),reset=$('#backup-reset');if(!out||!root.querySelectorAll)return;const boxes=[...root.querySelectorAll('#sec-backup .scam-list input')];
  const show=()=>{const picked=boxes.filter(b=>b.checked).map(b=>b.value);if(!picked.length){out.className='scam-result';out.innerHTML='<p>Tick the statements that are true to see what to improve.</p>';return}const v=backupVerdict(picked);out.className=`scam-result ${v.kind}`;out.innerHTML=`<b>${escape(v.title)}</b><p>${escape(v.body)}</p>${v.fixes.length?`<ol class="backup-fixes">${v.fixes.map(([,t,c,fix,slug])=>`<li${c?' class="critical"':''}><b>${escape(t.replace(/\. Tick this.*$/,''))}</b><span>${escape(fix)}${slug?` <a href="#learn/${slug}">Glossary: ${escape(glossaryMap.get(slug)[1])}</a>`:''}</span></li>`).join('')}</ol>`:''}`};
  for(const b of boxes)b.addEventListener('change',show);if(reset)reset.addEventListener('click',()=>{for(const b of boxes)b.checked=false;show()});show()}
