const sheetSteps=['Do not type the recovery phrase into any website, email, chat or form, and do not give it to anyone who offers to help. A genuine recovery never needs that.','Talk to the trusted person named above before doing anything else.','Get the wallet maker’s official app or device from their official website. Type the website address yourself; do not follow links from messages or ads.','Choose “restore” or “import an existing wallet” and enter the words in order, exactly as written. If an extra passphrase is used, enter it as well, or the wallet will open empty.','Check that the restored wallet shows what you expect before moving anything. Moving everything to a new wallet with a new recovery phrase afterwards is the safest choice.','Be wary of “recovery services” that ask for the phrase or an upfront fee. They are a common scam.'];
// Anything that looks like a secret is refused: 8+ recovery-style words (3–8 lowercase letters each), a 64-hex private key, an extended private key or a WIF key.
function looksSecret(raw){const v=String(raw||'').trim();if(!v)return false;const w=v.split(/\s+/);if(w.length>=8&&w.every(x=>/^[a-z]{3,8}$/.test(x)))return true;return/(^|[^0-9a-f])(0x)?[0-9a-f]{64}([^0-9a-f]|$)/i.test(v)||/\b[xyzt]prv[1-9A-HJ-NP-Za-km-z]{20,}/.test(v)||/^[5KL9c][1-9A-HJ-NP-Za-km-z]{50,51}$/.test(v)}
function sheetHtml(values,date){const v=values||{},row=([id,label])=>{const val=String(v[id]||'').trim();const shown=val&&val!=='Not sure'?escape(val):'<span class="blank" aria-label="blank, to fill in by hand"></span>';return`<tr><th scope="row">${label}</th><td>${shown}</td></tr>`};
  return`<div class="sheet-paper"><div class="between"><b class="sheet-title">Crypto wallet backup instructions</b><span class="tiny">Prepared ${escape(date)}</span></div><p class="sheet-warning">This sheet does <b>not</b> contain the recovery phrase. Keep it apart from the phrase, for example with a will or with your attorney.</p><table class="sheet-table">${sheetFields.map(row).join('')}</table><h3>If you are reading this to recover the wallet</h3><ol>${sheetSteps.map(t=>`<li>${escape(t)}</li>`).join('')}</ol><p class="tiny">Made with the free backup sheet at ea-la.github.io/FYNX-Wallet/#security/sheet. General guidance only, not legal or financial advice.</p></div>`}
function planSheet(){return `<section class="card scam-check plan-sheet" id="sec-sheet" aria-labelledby="sheet-h"><span class="eyebrow">PRINTABLE · ANY WALLET</span><h2 id="sheet-h">Backup instructions for your family</h2><p class="muted">If something happened to you, would someone you trust know how to recover your crypto? Fill in what you want (every field is optional), then print it or save it as a PDF to keep with your will. Blank fields print as lines to fill in by hand. Nothing you type is sent or saved, and it is cleared when you leave this page. <b>Never type the recovery phrase itself.</b></p><form class="sheet-form" id="sheet-form" autocomplete="off">${sheetFields.map(([id,label,opt])=>`<label class="label" for="sheet-${id}">${label}${Array.isArray(opt)?`<select class="control" id="sheet-${id}" data-field="${id}">${opt.map(o=>`<option>${o}</option>`).join('')}</select>`:`<input class="control" id="sheet-${id}" data-field="${id}" maxlength="60" placeholder="${opt}" spellcheck="false">`}</label>`).join('')}</form><p class="error" id="sheet-error" role="alert"></p><div class="sheet-preview" id="sheet-out" aria-label="Sheet preview"></div><div class="sheet-actions"><button class="button" type="button" id="sheet-print">Print or save as PDF</button><button class="button light" type="button" id="sheet-clear">Clear</button></div></section>`}
function bindPlanSheet(){const form=$('#sheet-form'),out=$('#sheet-out'),err=$('#sheet-error');if(!form||!out||!form.querySelectorAll)return;const fields=[...form.querySelectorAll('[data-field]')];const date=new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
  const show=()=>{const values={};for(const f of fields){if(looksSecret(f.value)){f.value='';if(err)err.textContent='That looked like a recovery phrase or private key, so it was cleared. Never type it into any website, including this one.'}values[f.dataset.field]=f.value}out.innerHTML=sheetHtml(values,date)};
  for(const f of fields){f.addEventListener('input',()=>{if(err)err.textContent='';show()});f.addEventListener('change',show)}
  $('#sheet-clear')?.addEventListener('click',()=>{form.reset();if(err)err.textContent='';show()});
  $('#sheet-print')?.addEventListener('click',()=>{const root=document.documentElement;let copy=document.getElementById('print-root');if(!copy){copy=document.createElement('div');copy.id='print-root';document.body.appendChild(copy)}copy.innerHTML=out.innerHTML;root.classList.add('print-sheet');const done=()=>{root.classList.remove('print-sheet');copy.innerHTML='';window.removeEventListener('afterprint',done)};window.addEventListener('afterprint',done);window.print()});show()}
function scamVerdict(selected){const set=new Set(selected);if(!set.size)return{kind:'',title:'',body:''};
  const critical=scamSigns.filter(([id,,c])=>c&&set.has(id));
  if(critical.length)return{kind:'danger',title:'Stop. This is a scam.',body:'Asking for a recovery phrase or key, asking you to send crypto to “verify” or “unlock” a wallet, or charging a fee before you can withdraw are never part of a genuine wallet service. Do not send anything, do not share any phrase or key, and stop replying.'};
  if(set.size>=2)return{kind:'danger',title:'Very likely a scam.',body:`${set.size} common warning signs together is a strong pattern. Stop, do not send or approve anything, and check independently through the official website you typed yourself.`};
  return{kind:'warn',title:'Be careful: this is a common warning sign.',body:'One sign does not prove a scam, but slow down. Verify through an official website you typed yourself, never through a link or contact you were sent.'}}
function bindScamCheck(){const root=$('#app'),out=$('#scam-result'),reset=$('#scam-reset');if(!out||!root.querySelectorAll)return;const boxes=[...root.querySelectorAll('#sec-scam .scam-list input')];
  const show=()=>{const v=scamVerdict(boxes.filter(b=>b.checked).map(b=>b.value));out.className=`scam-result ${v.kind}`;out.innerHTML=v.title?`<b>${escape(v.title)}</b><p>${escape(v.body)}</p>`:'<p>No warning signs ticked.</p>'};
  for(const b of boxes)b.addEventListener('change',show);if(reset)reset.addEventListener('click',()=>{for(const b of boxes)b.checked=false;show()});show()}
const learnTopics=[['basics','Basics'],['keys','Keys and safety'],['sending','Sending and fees'],['tokens','Tokens and swaps'],['buying','Buying and selling']];
// [slug, term, topic, plain-English definition, search synonyms, related term slugs, optional [href, label] link on this site]
const glossary=[
  ['wallet','Wallet','basics','An app or device that holds the keys to your crypto addresses and lets you approve transactions. The crypto itself is recorded on a blockchain; the wallet holds what proves it is yours.','app account',['self-custody','recovery-phrase','hardware-wallet'],['features/keys','How FYNX plans to handle keys']],
  ['self-custody','Self-custody (non-custodial)','basics','You hold the keys yourself, so no company can move your crypto, freeze it or recover it for you. It gives you full control, and full responsibility for keeping your backup safe.','non-custodial own keys',['custodial','recovery-phrase'],['features/keys','The planned FYNX design']],
  ['custodial','Custodial account','basics','A company holds the keys on your behalf, as many exchanges do. You sign in with a password, and the company moves crypto on your instructions. If the company fails or freezes your account, you may lose access.','exchange account',['self-custody']],
  ['blockchain','Blockchain','basics','A shared public record of transactions kept by many computers. Once a transaction is confirmed in it, it cannot be edited or deleted.','ledger chain',['network','confirmation','block-explorer']],
  ['network','Network','basics','A specific blockchain, such as Ethereum, Base, Bitcoin or Solana. Assets on one network are separate from assets on another, even when they share a name like USDC.','chain blockchain',['layer-2','bridge','public-address'],['networks','Planned networks and address checker']],
  ['stablecoin','Stablecoin','basics','A token designed to keep a steady value, usually one U.S. dollar. USDC is an example. It depends on its issuer and the reserves behind it, and it is not a bank deposit or government-insured.','usdc dollar',['token','native-asset']],
  ['testnet','Test network (testnet)','basics','A practice copy of a network where coins have no real value, used for testing before anything goes live. Sepolia is an Ethereum test network. Never pay real money for test coins.','sepolia test',['network']],
  ['recovery-phrase','Recovery phrase (seed phrase)','keys','A list of 12 or 24 words that can rebuild a wallet on any device. Anyone who has it controls everything in that wallet. Write it down offline and never type it into a website, chat or form.','seed phrase mnemonic backup words',['private-key','phishing','self-custody'],['security','Is this a scam? self-check']],
  ['private-key','Private key','keys','The secret that signs transactions for one address. A recovery phrase can generate many private keys. Whoever has the key can move the funds, so it is never shared.','secret key',['recovery-phrase','signing','public-address']],
  ['public-address','Public address','keys','What you share so people can send you crypto, a bit like an account number. It is safe to share. On Ethereum and Base it starts with 0x followed by 40 characters.','wallet address receive',['checksum','address-poisoning','network'],['networks','Check an address format']],
  ['hardware-wallet','Hardware wallet','keys','A small physical device that keeps keys offline and shows each transaction on its own screen for you to approve. Malware on your computer cannot read the keys from it.','ledger trezor cold wallet',['wallet','signing'],['features/keys','Hardware wallets in the FYNX plan']],
  ['signing','Signing (approving)','keys','Using your private key to approve a transaction or message. Your wallet does this when you press approve. A signature cannot be taken back once the transaction is confirmed.','sign approve signature',['transaction','token-approval'],['features/review','Practise on an example review screen']],
  ['phishing','Phishing','keys','A fake website, email or message that imitates a real service to steal your recovery phrase or trick you into signing something. Type official addresses yourself instead of following links.','scam fake site',['recovery-phrase','address-poisoning'],['security','Is this a scam? self-check']],
  ['address-poisoning','Address poisoning','keys','A scam where tiny transfers are sent from an address that looks like one you use, so you copy the wrong one from your history later. Always compare the full address, not just the start and end.','lookalike look-alike fake address',['public-address','checksum'],['features/review','What to check before sending']],
  ['checksum','Address checksum (EIP-55)','keys','The mix of capital and small letters in an Ethereum-style address is a built-in check. If one character is changed, the capitals stop matching, so wallets can warn about a likely typo.','eip-55 capital letters typo',['public-address'],['networks','Try the address checker']],
  ['transaction','Transaction','sending','A signed instruction to move assets or use a smart contract. It is sent to the network, waits as pending, and is final once confirmed.','transfer send',['network-fee','confirmation','transaction-hash']],
  ['network-fee','Network fee (gas)','sending','What you pay the network to process a transaction. It goes to the network, not to the recipient, and changes with demand. On Ethereum and Base it is paid in ETH, so you need a little ETH even to send USDC.','gas fee cost gwei',['native-asset','transaction'],['features/review','Fees on the review screen']],
  ['confirmation','Confirmation','sending','A transaction is confirmed once the network includes it in a block. Until then it shows as pending. After confirmation it cannot be reversed or cancelled.','pending final block',['transaction','blockchain']],
  ['transaction-hash','Transaction ID (hash)','sending','A unique code that identifies one transaction, which you can look up on a block explorer. On Ethereum it is 0x followed by 64 characters, longer than an address.','txid tx hash receipt',['block-explorer','transaction']],
  ['block-explorer','Block explorer','sending','A website that shows public blockchain records: addresses, balances and transactions. Etherscan is a common one for Ethereum. Anyone can see what is recorded there.','etherscan basescan explorer',['transaction-hash','blockchain']],
  ['layer-2','Layer 2','sending','A network that runs on top of Ethereum to make transactions cheaper and faster, while relying on Ethereum for security. Base is a layer 2 network.','l2 base rollup',['network','bridge']],
  ['bridge','Bridge','sending','A service that moves assets from one network to another. Bridges add their own risks, and a token received through a bridge can differ from the version issued directly on that network.','cross-chain move between networks',['network','layer-2']],
  ['token','Token','tokens','An asset created on an existing network by a smart contract, such as USDC on Ethereum. The same name on two networks means two separate tokens and balances.','erc-20 coin',['native-asset','smart-contract','stablecoin']],
  ['native-asset','Native asset','tokens','The built-in coin of a network, used to pay its fees: ETH on Ethereum and Base, SOL on Solana, BTC on Bitcoin.','eth sol btc coin',['network-fee','token']],
  ['smart-contract','Smart contract','tokens','A program stored on a blockchain that runs exactly as written. Tokens, exchanges and many apps are smart contracts. Mistakes or malicious code in one can put funds at risk.','contract dapp',['token','token-approval','dex']],
  ['swap','Swap','tokens','Exchanging one asset for another on the same network, for example ETH for USDC, usually through a decentralized exchange.','exchange trade convert',['slippage','dex','token-approval'],['features/swap','Swaps in the FYNX plan']],
  ['slippage','Slippage and minimum received','tokens','Prices can move between the quote and the moment a swap completes. A minimum amount received protects you: if the price moves too far, the swap fails instead of filling at a worse rate.','price impact minimum received',['swap'],['features/swap','How the planned swap shows it']],
  ['token-approval','Token approval (allowance)','tokens','A permission that lets a smart contract move a token from your wallet, often needed before a swap. An unlimited approval can be abused later, so approve only the amount you need and revoke ones you no longer use.','allowance permission approve revoke',['smart-contract','signing'],['security','Before you approve anything']],
  ['dex','Decentralized exchange (DEX)','tokens','An exchange made of smart contracts, which lets you swap directly from your own wallet without handing your crypto to a company. Uniswap is an example.','uniswap amm exchange',['swap','smart-contract']],
  ['on-ramp','On-ramp','buying','A service that turns card or bank money into crypto delivered to your wallet. It is run by a regulated payment provider, which sets its own fees and checks.','buy crypto card bank',['kyc','off-ramp','spread'],['features/buy','Buying in the FYNX plan']],
  ['off-ramp','Off-ramp','buying','The reverse of an on-ramp: selling crypto and receiving money in a bank account.','sell cash out withdraw',['on-ramp','kyc']],
  ['kyc','Identity checks (KYC)','buying','“Know your customer” checks, such as confirming your name, address and ID, that regulated providers must run before you can buy or sell with card or bank money.','know your customer verification id',['on-ramp']],
  ['spread','Spread','buying','The gap between the price to buy and the price to sell. Together with fees, it is part of what buying crypto actually costs, so compare the total you pay with what you receive.','price difference cost',['on-ramp','network-fee']],
];
const glossaryMap=new Map(glossary.map(g=>[g[0],g]));
function learnPage(){return intro('Crypto words, explained.','A plain-English glossary of the terms you will meet in any wallet. Education only, not financial advice.',`<div class="faq-tools"><label class="sr-only" for="learn-search">Search the glossary</label><input class="control faq-search" id="learn-search" type="search" placeholder="Search terms, e.g. gas, seed phrase, approval" autocomplete="off"></div><div class="tour-jump learn-topics" role="group" aria-label="Filter by topic"><button type="button" class="tour-chip" data-topic="" aria-pressed="true">All</button>${learnTopics.map(([id,name])=>`<button type="button" class="tour-chip" data-topic="${id}" aria-pressed="false">${name}</button>`).join('')}</div><p class="hint faq-count" id="learn-count" role="status" aria-live="polite">${glossary.length} terms</p>${learnTopics.map(([id,name])=>`<section class="faq-group learn-group" data-topic="${id}" aria-labelledby="lt-${id}"><h2 id="lt-${id}">${name}</h2><div class="learn-grid">${glossary.filter(g=>g[2]===id).map(([slug,term,,def,aka,rel,link])=>`<article class="card term" id="term-${slug}" data-topic="${id}" data-search="${escape(`${term} ${def} ${aka}`.toLowerCase())}"><h3>${term}</h3><p>${def}</p>${rel.length?`<p class="term-related">Related: ${rel.map(r=>`<a href="#learn/${r}">${glossaryMap.get(r)[1]}</a>`).join(', ')}</p>`:''}<div class="term-foot">${link?`<a class="textlink" href="#${link[0]}">${link[1]} ↗</a>`:'<span></span>'}<button type="button" class="term-copy" data-slug="${slug}" aria-label="Copy link to ${escape(term)}">Copy link</button></div></article>`).join('')}</div></section>`).join('')}<div class="faq-empty" id="learn-empty" hidden><p>No terms match. Try a shorter word, or <a href="#faq">browse the Questions page</a>.</p></div><div class="info-box">These explanations are general education about how crypto wallets work. They are not financial, legal or tax advice, and they describe no live FYNX service. ${button('Join the waitlist ↗','waitlist','light')}</div>`)}
function shareLink(path){return `${location.href.split('#')[0]}#${path}`}
async function copyShareLink(btn,path){const url=shareLink(path),done=t=>{btn.textContent=t;setTimeout(()=>{btn.textContent='Copy link'},2000)};try{await navigator.clipboard.writeText(url);done('Link copied')}catch{history.replaceState(null,'',`#${path}`);done('Link in address bar')}}
function highlight(el){if(!el)return;el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),2200)}
function bindLearn(section=''){const root=$('#app'),input=$('#learn-search');if(!input||!root.querySelectorAll)return;const cards=[...root.querySelectorAll('.term')],chips=[...root.querySelectorAll('.learn-topics .tour-chip')];let topic='';
  const apply=()=>{const terms=input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);let shown=0;for(const c of cards){const hit=(!topic||c.dataset.topic===topic)&&terms.every(t=>c.dataset.search.includes(t));c.hidden=!hit;if(hit)shown++}for(const g of root.querySelectorAll('.learn-group'))g.hidden=![...g.querySelectorAll('.term')].some(c=>!c.hidden);$('#learn-empty').hidden=shown>0;$('#learn-count').textContent=shown===cards.length?`${cards.length} terms`:`${shown} of ${cards.length} terms`};
  input.addEventListener('input',apply);
  for(const chip of chips)chip.addEventListener('click',()=>{topic=chip.dataset.topic;for(const c of chips)c.setAttribute('aria-pressed',String(c===chip));apply()});
  root.addEventListener('click',e=>{const b=e.target.closest('.term-copy');if(b)copyShareLink(b,`learn/${b.dataset.slug}`)});
  if(section)requestAnimationFrame(()=>{const t=document.getElementById(`term-${section}`);goToSection(t,false);const h=t&&t.querySelector('h3');if(h){h.setAttribute('tabindex','-1');h.focus({preventScroll:true})}highlight(t)})}
const closedRoute=r=>['wallet','assets','activity','swap','send','receive','settings','buy','sell','login'].includes(r)||r.startsWith('asset/')||r.startsWith('transaction/');
const featureSections=()=>[...featureTour.map(([id])=>id),'review'];
const pageSections={security:['scam','approve','backup','sheet'],networks:['plan','check']};
function bindSections(section,prefix){if(section)requestAnimationFrame(()=>goToSection(document.getElementById(`${prefix}-${section}`),false))}
const sitePages=[['features','Features','A tour of the proposed wallet, with an example review screen.'],['networks','Networks','Planned networks and an address checker.'],['security','Security','A scam self-check, a recovery-phrase backup check, a printable backup instructions sheet and what to verify before approving.'],['faq','Questions','Searchable answers about the waitlist and product.'],['learn','Glossary','Plain-English crypto terms, searchable by topic.'],['waitlist','Join the waitlist','Request availability updates by email.'],['privacy','Waitlist privacy','What the waitlist keeps and for how long.']];
function notFound(){return intro('This page doesn’t exist.','The link may be mistyped or out of date. Nothing is wrong with your browser.',`<nav class="security-grid notfound-links" aria-label="Pages on this site">${sitePages.map(([h,t,d])=>`<a class="card security-card" href="#${h}"><h3>${t} ↗</h3><p>${d}</p></a>`).join('')}</nav><div class="info-box">Looking for a wallet account? Public accounts are not open yet. ${button('Back to the homepage','home','light')}</div>`)}
const pageTitles={notfound:'Page not found',home:'',features:'Features',networks:'Networks',security:'Security',waitlist:'Join the waitlist',login:'Log in',privacy:'Waitlist privacy',terms:'Preview terms',faq:'Questions',learn:'Crypto glossary'};
function syncPageChrome(r){for(const link of document.querySelectorAll('.mobilenav a')){if(link.getAttribute('href')===`#${r}`)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')}document.title=pageTitles[r]?`${pageTitles[r]} · FYNX Wallet`:'FYNX Wallet — Your crypto. Simply yours.';for(const link of document.querySelectorAll('.globalnav a')){const current=link.getAttribute('href')===`#${r}`;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')}}
function setFooterYear(){const y=document.querySelector('[data-year]');if(y)y.textContent=String(new Date().getFullYear())}
function focusPageHeading(){const heading=document.querySelector('#app h1');if(!heading)return;heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}
function render(){let r=location.hash.slice(1)||'home',content,section='';const deep=/^features\/([a-z]+)$/.exec(r);if(deep&&featureSections().includes(deep[1])){section=deep[1];r='features'}const part=/^(security|networks)\/([a-z]+)$/.exec(r);if(part&&pageSections[part[1]].includes(part[2])){section=part[2];r=part[1]}const sub=/^(learn|faq)\/([a-z0-9-]+)$/.exec(r);if(sub&&(sub[1]==='learn'?glossaryMap.has(sub[2]):faqSlugs().includes(sub[2]))){section=sub[2];r=sub[1]}if(r!=='home'&&!closedRoute(r)&&!Object.hasOwn(pageTitles,r))r='notfound';if(closedRoute(r))r='login';syncPageChrome(r);if(r==='notfound')content=notFound();else if(r==='home')content=home();else if(r==='login'||r==='waitlist')content=waitlist(r==='login');else if(r==='features')content=featuresPage();else if(r==='networks')content=networks();else if(r==='security')content=security();else if(r==='privacy')content=privacy();else if(r==='terms')content=intro('A clear starting point.','Pre-launch website notice.',`<article class="longform"><p>FYNX Wallet is in development. This website describes a proposed product. Illustrative balances and features do not represent live financial services, executable prices, or guaranteed availability.</p><p>Waitlist registration requests availability updates; it does not create a trading, payment, or custody account. Eligibility, supported regions, product terms, fees, and launch timing are not yet finalized.</p>${button('Join the waitlist')}</article>`);else if(r==='faq')content=faq();else if(r==='learn')content=learnPage();else content=waitlist(true);$('#app').innerHTML=content;if($('#waitlist-form')){$('#waitlist-form').onsubmit=handleWaitlistSubmit;bindWaitlistForm($('#waitlist-form'))}if(r==='faq')bindFaq(section);if(r==='learn')bindLearn(section);if(r==='features')bindFeatures(section);if(r==='networks'){bindAddressTool();bindSections(section,'net')}if(r==='security'){bindScamCheck();bindBackupCheck();bindPlanSheet();bindSections(section,'sec')}}

window.addEventListener('hashchange',()=>{const deep=/^#(?:features|learn|faq)\/[a-z0-9-]+$/.test(location.hash);render();if(!deep){window.scrollTo(0,0);focusPageHeading()}});setupMenu();setFooterYear();render();connectFirebase();
